fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // We can leverage Vec::split_off to split the vector at `idx`.
    // The first part remains in `arr`, the second part is returned in `tail`.
    let mut front = arr;
    let mut tail = front.split_off(idx);
    // Insert the new value at the boundary.
    front.push(value);
    // Append the remainder back on.
    front.append(&mut tail);
    front
}

